    'vi': 'Bằng\x20việc\x20gửi\x20số\x20điện\x20thoại,\x20bạn\x20đồng\x20ý\x20rằng\x20số\x20này\x20có\x20thể\x20được\x20dùng\x20để\x20xác\x20minh\x20điều\x20kiện\x20và\x20liên\x20hệ\x20về\x20hoạt\x20động\x20này\x20theo\x20chính\x20sách\x20quyền\x20riêng\x20tư\x20của\x20chúng\x20tôi.\x20Vui\x20lòng\x20không\x20gửi\x20số\x20của\x20người\x20khác\x20khi\x20chưa\x20được\x20phép.',
